fn find_median(a: &[i32], b: &[i32]) -> i32 {
    let n = a.len();
    debug_assert!(n > 0 && n == b.len(), "Arrays must be non‐empty and of equal length");

    if n % 2 == 1 {
        // Odd length → return the middle element of `a`
        a[n / 2]
    } else {
        // Even length → average the last element of the lower half of `a`
        // and the first element of `b`, rounding down.
        let x = a[n / 2 - 1] as i64;
        let y = b[0] as i64;
        // Use Euclidean division to get floor(sum / 2) even when sum < 0
        (x + y).div_euclid(2) as i32
    }
}

